mapper.select:
SELECT  FROM knowledge_evaluation_review_revision r
WHERE r.tenant_id = #{caller.tenantId} AND r.owner_id = #{caller.userId}
    AND r.run_id = #{runId} AND r.manifest_digest = #{manifest} AND r.question_id = #{questionId}
AND r.revision < #{before}
ORDER BY r.revision DESC LIMIT #{limit}

mapper.update:
UPDATE knowledge_evaluation_review_head SET revision = #{row.revision}
WHERE tenant_id = #{row.tenantId} AND owner_id = #{row.ownerId} AND run_id = #{row.runId}
    AND manifest_digest = #{row.manifestDigest} AND question_id = #{row.questionId} AND revision = #{expected}

mapper.select:
SELECT , NULL AS snapshot_json, b.note, b.selected_by, b.created_at
FROM knowledge_evaluation_baseline_head h JOIN knowledge_evaluation_baseline b USING (dataset_id, dataset_revision, revision)
WHERE b.tenant_id = #{caller.tenantId} AND b.owner_id = #{caller.userId} AND b.dataset_id = #{datasetId} AND b.dataset_revision = #{datasetRevision}

SELECT , NULL AS snapshot_json, NULL AS note, b.selected_by, b.created_at
FROM knowledge_evaluation_baseline b WHERE b.tenant_id = #{caller.tenantId} AND b.owner_id = #{caller.userId}
    AND b.dataset_id = #{datasetId} AND b.dataset_revision = #{datasetRevision}
AND b.revision < #{before}
ORDER BY b.revision DESC LIMIT #{limit}

mapper.update:
UPDATE knowledge_evaluation_baseline_head SET revision = #{row.revision}
WHERE tenant_id = #{row.tenantId} AND owner_id = #{row.ownerId} AND dataset_id = #{row.datasetId}
    AND dataset_revision = #{row.datasetRevision} AND revision = #{expected}
